-- The source register as data (#29): the attribution, licence and conditions
-- of every source the platform attributes, so the API's contract.source and
-- contract.source_note resolve for every row (0312), static sources included.
-- Generated from the platform's machine-authoritative attribution table (the
-- strings the register states, verbatim) and the register's own dates. A
-- change is a new migration, after the data steward signs the register row.
--
--   attribution_text, source_url, licence_label: the attribution table, verbatim;
--   share_alike: CC BY-SA or ODbL (share-alike on the work or the database);
--   changes_statement: the change marker the attribution string itself states;
--   use_classes: read off the licence and the register's flags: consumer only
--     for a source restricted to consumer answers, to no redistribution or to
--     a purpose, or with no licence text (open-data class, statutory AFIR, the
--     Autobahn GmbH API, Toll Collect SID); consumer and non_commercial for
--     CC BY-SA (sale: aggregates only); all three otherwise;
--   verified_on: the newest date the register row's verification states;
--   register_version: the register's own date (2026-11-14).
-- Notes are the condition and purpose sentences a caller must show verbatim;
-- the MTS-K purpose note exists in German only and is stored verbatim under
-- both languages, as the platform shows it.
--
-- rollback: drop table public.source_register_notes, public.source_register;
--   delete from schema_migrations where version = 309;

create table public.source_register (
    source_id             text primary key check (source_id ~ '^[a-z0-9_]+$'),
    attribution_text      text not null check (btrim(attribution_text) <> ''),
    source_url            text not null check (source_url ~ '^https://'),
    licence_label         text not null check (btrim(licence_label) <> ''),
    share_alike           boolean not null,
    share_alike_database  boolean not null,
    changes_statement     text,
    use_classes           text[] not null check (cardinality(use_classes) > 0 and use_classes <@ array['consumer', 'non_commercial', 'commercial']),
    consumer_answers_only boolean not null,
    no_redistribution     boolean not null,
    verified_on           date,
    register_version      date not null,
    check (not share_alike_database or share_alike)
);
comment on table public.source_register is 'The data-source register as data: one row per source id the platform attributes (0309). Read by the contract views (0312); written only by migrations.';

create table public.source_register_notes (
    source_id text not null references public.source_register,
    note_kind text not null check (note_kind in ('condition', 'purpose')),
    lang      text not null check (lang in ('de', 'en')),
    body      text not null check (btrim(body) <> ''),
    primary key (source_id, note_kind, lang)
);
comment on table public.source_register_notes is 'The sentences a caller must show verbatim beside a source''s rows: its condition and purpose notes, per language (0309).';


