  ('viafrei_rules', 'Verkehrsregeln: ViaFrei, eigene Zusammenstellung aus amtlichen Quellen (StVO, StVZO, 35. BImSchV, StVG, EmoG, AFIR); jede Aussage mit Quelle und Prüfdatum — informativ, keine Rechtsberatung / Road rules: ViaFrei, our own compilation from official sources; every statement carries its source and the date it was read — informational, not legal advice', 'https://viafrei.de', 'ViaFrei editorial content (informational, not legal advice)', false, false, null, array['consumer', 'non_commercial', 'commercial'], false, false, '2026-09-19'::date, '2026-11-14'::date),
  ('viafrei_watch', 'Beobachtung: ViaFrei, eigener Dienst — jede Meldung nennt die Quelle der Daten, die sie ausgelöst haben / Watch: ViaFrei, our own service — every report names the source of the data behind it', 'https://viafrei.de', 'ViaFrei service metadata (no provider data)', false, false, null, array['consumer', 'non_commercial', 'commercial'], false, false, '2026-09-20'::date, '2026-11-14'::date),
