insert into public.source_register_notes (source_id, note_kind, lang, body) values
  ('dwd_road', 'condition', 'de', 'Die Daten der Glättemeldeanlagen stellen ungeprüfte Punktmessungen dar und spiegeln nicht die Verhältnisse auf einem Straßenabschnitt wider. Es besteht kein Anspruch auf regelmäßige und vollständige Datenlieferungen.'),
  ('dwd_road', 'condition', 'en', 'The road-weather station data are unverified point measurements and do not reflect conditions on a road section; there is no entitlement to regular and complete deliveries. Binding original: „Die Daten der Glättemeldeanlagen stellen ungeprüfte Punktmessungen dar und spiegeln nicht die Verhältnisse auf einem Straßenabschnitt wider. Es besteht kein Anspruch auf regelmäßige und vollständige Datenlieferungen.“'),
  ('hh_verkehrskameras', 'condition', 'de', '„… wird die Übertragung ins Internet gelegentlich aus Datenschutzgründen von der Verkehrsleitzentrale unterbunden, sodass die Kamerabilder für Außenstehende nicht zuverlässig 24h am Tag verfügbar sind.“ (Freie und Hansestadt Hamburg)'),
  ('hh_verkehrskameras', 'condition', 'en', 'The publisher states that the internet transmission is occasionally stopped by the Verkehrsleitzentrale for data-protection reasons, so the camera images are not reliably available 24 hours a day („… nicht zuverlässig 24h am Tag verfügbar …“).'),
  ('kvb_lifts', 'condition', 'de', 'Die Kölner Verkehrs-Betriebe AG stellt die Daten ohne jede Gewähr bereit.'),
  ('kvb_lifts', 'condition', 'en', 'Kölner Verkehrs-Betriebe AG provides the data without any warranty.'),
  ('lorry_bast_langlkw', 'condition', 'de', 'Die hier vorliegenden Daten erheben keinen Anspruch auf Vollständigkeit oder Richtigkeit. Sie sind auch von keiner rechtlichen oder amtlichen Bedeutung. Die Daten sind weder für Navigation noch für ähnliche Zwecke geeignet.'),
  ('lorry_bast_langlkw', 'condition', 'en', 'The data make no claim to be complete or correct. They have no legal or official meaning either. The data are not suitable for navigation or similar purposes (our translation of the publisher''s notice).'),
  ('lorry_dresden_verbotszonen', 'condition', 'de', 'Lkw-Verbote stehen hier als Information, nicht als Rechtsberatung: wen und wann ein Verbot bindet, sagt allein die Beschilderung vor Ort.'),
  ('lorry_dresden_verbotszonen', 'condition', 'en', 'Lorry bans are shown here as information, not legal advice: only the signs on site say whom and when a ban binds.'),
  ('lorry_hb_durchfahrtshoehen', 'condition', 'de', 'Höhen und Gewichte der VMZ Bremen stehen hier so, wie sie veröffentlicht sind (gelesen am {date}). Verbindlich ist allein die Beschilderung vor Ort; die Daten sind nicht für die Routenführung bestimmt. Fehlt eine Angabe, heißt das nicht, dass keine Beschränkung besteht.'),
  ('lorry_hb_durchfahrtshoehen', 'condition', 'en', 'VMZ Bremen''s heights and weights are shown as published (read on {date}). Only the signs on site are binding; the data is not for route guidance. A missing entry does not mean there is no restriction.'),
  ('lorry_hb_fuehrungshoehen', 'condition', 'de', 'Höhen und Gewichte der VMZ Bremen stehen hier so, wie sie veröffentlicht sind (gelesen am {date}). Verbindlich ist allein die Beschilderung vor Ort; die Daten sind nicht für die Routenführung bestimmt. Fehlt eine Angabe, heißt das nicht, dass keine Beschränkung besteht.'),
  ('lorry_hb_fuehrungshoehen', 'condition', 'en', 'VMZ Bremen''s heights and weights are shown as published (read on {date}). Only the signs on site are binding; the data is not for route guidance. A missing entry does not mean there is no restriction.'),
  ('lorry_hh_gst_netz', 'condition', 'de', 'Das Großraum- und Schwertransport-Netz hilft beim Antrag in VEMAGS und ist keine Erlaubnis: ein Großraum- oder Schwertransport braucht seine eigene Erlaubnis oder Genehmigung (§ 29 Abs. 3, § 46 Abs. 1 StVO), und es gilt die Beschilderung vor Ort. Das Netz ist die Zusammenstellung des LBV der am häufigsten benötigten Strecken; es nennt keine zulässigen Maße, Gewichte oder Achslasten, und welche Strecke ein Transport fahren darf, legt seine Erlaubnis fest.'),
  ('lorry_hh_gst_netz', 'condition', 'en', 'The oversize and heavy transport network helps with an application in VEMAGS and is no permit: an oversize or heavy transport needs its own permit or authorisation (§ 29(3), § 46(1) StVO), and the signs on site apply. The network is the LBV''s compilation of the routes most often needed; it names no permitted dimensions, weights or axle loads, and the route a transport may take is the one its permit sets.'),
  ('mobilithek_roadworks_akd', 'condition', 'de', 'Geplante Arbeitsstellen kürzerer Dauer werden kurzfristig geplant und oft geändert; sie ersetzen weder eine Genehmigung für Großraum- und Schwertransporte noch die Wegkontrolle vor Fahrtantritt.'),
  ('mobilithek_roadworks_akd', 'condition', 'en', 'Planned short-duration roadworks are planned at short notice and often changed; they replace neither a permit for oversize and heavy transports nor the route check before setting off (our translation of the publisher''s note).'),
  ('mobilithek_sperrinfosys_sn', 'condition', 'de', 'Für die Richtigkeit und Vollständigkeit der Angaben sind die angeschlossenen, jeweils zuständigen Verkehrsbehörden verantwortlich.'),
  ('mobilithek_sperrinfosys_sn', 'condition', 'en', 'The connected traffic authorities responsible in each case are responsible for the accuracy and completeness of the information (our translation of the publisher''s condition of use).'),
  ('mobilithek_traffic_bw', 'condition', 'de', 'Amtliche Meldungen des Verkehrswarndienstes der Landesmeldestelle Baden-Württemberg, veröffentlicht auf Grundlage der Rahmenrichtlinie für den Verkehrswarndienst (RVWD); Nutzungsbedingung ist die RVWD. Der Meldungstext wird ungekürzt und nur aktuell wiedergegeben.'),
  ('mobilithek_traffic_bw', 'condition', 'en', 'Official traffic-warning-service (Verkehrswarndienst) messages of the Landesmeldestelle Baden-Württemberg, published under the Rahmenrichtlinie für den Verkehrswarndienst (RVWD); the condition of use is the RVWD. The message text is shown unabridged and only while current.'),
  ('tankerkoenig', 'purpose', 'de', 'Hinweis zu den Kraftstoffpreisdaten (MTS-K): Diese Daten dürfen ausschließlich zum Zweck der Verbraucherinformation verwendet werden; daher ist insbesondere eine Verwendung der Daten zur Information der Mineralölwirtschaft und/oder ihrer IT-Dienstleister nicht erlaubt.'),
  ('tankerkoenig', 'purpose', 'en', 'Hinweis zu den Kraftstoffpreisdaten (MTS-K): Diese Daten dürfen ausschließlich zum Zweck der Verbraucherinformation verwendet werden; daher ist insbesondere eine Verwendung der Daten zur Information der Mineralölwirtschaft und/oder ihrer IT-Dienstleister nicht erlaubt.'),
  ('toll_collect_sid', 'condition', 'de', 'Lkw-Stellplatzbelegung: Toll Collect GmbH, Stellplatz-Informationsdienst (SID) via Mobilithek. Die Angaben können ungenau, unvollständig oder veraltet sein; keine Gewähr. Es gelten die Nutzungsbedingungen, Abschnitt 2: https://viafrei.de/terms#sid'),
  ('toll_collect_sid', 'condition', 'en', 'Truck-parking occupancy: Toll Collect GmbH, Stellplatz-Informationsdienst (SID) via Mobilithek. The figures may be inaccurate, incomplete or out of date; no warranty. ViaFrei''s terms of use, section 2, apply: https://viafrei.de/en/terms#sid');
